          "Cash Value",
          "/kæʃ ˈvæljuː/",
          "noun",
          "The savings or investment component of a permanent life insurance policy that accumulates over time. Cash value grows tax-deferred, can be accessed through loans or withdrawals, and is distinct from the death benefit — though accessing it can affect the benefit paid at death.",
          "field",
          "Cash value is the living benefit of a permanent policy — available to the policyholder during their lifetime. Its growth, accessibility, and interaction with the death benefit vary by policy type. Understanding the mechanics before accessing it prevents unintended consequences.",
