          "Variable Life",
          "/ˈvɛəriəbəl laɪf/",
          "noun",
          "A permanent life insurance policy in which the cash value is invested in sub-accounts — similar to mutual funds — whose performance directly affects the cash value and, in some versions, the death benefit. Returns are not guaranteed and can decline.",
          "field",
          "Variable life introduces market risk into life insurance. The potential for higher cash value growth comes with the possibility of loss. The death benefit may have a guaranteed floor, but the cash value does not. It is a product that requires investment sophistication alongside insurance planning.",
