          "Waiver of Premium",
          "/ˈweɪvər əv ˈpriːmiəm/",
          "noun",
          "A rider that suspends premium payments if the policyholder becomes totally disabled and unable to work, while keeping the policy in force. Coverage continues during the disability period without requiring payment.",
