          "A fixed dollar amount paid by the insured for a specific healthcare service — such as a doctor's visit or prescription — at the time of service. The insurer pays the remainder. Copays do not typically count toward the deductible but may count toward the out-of-pocket maximum.",
          "field",
          "Copays are the most visible part of health insurance cost — paid every time a service is used. They provide predictability for routine care. Knowing which services carry copays versus coinsurance versus full cost-sharing helps avoid unexpected bills.",
