          "Coinsurance",
          "/ˌkoʊɪnˈʃʊərəns/",
          "noun",
          "The percentage of covered medical costs the insured pays after the deductible has been met. For example, an 80/20 coinsurance arrangement means the insurer pays 80 percent and the insured pays 20 percent of covered costs until the out-of-pocket maximum is reached.",
          "course",
          "Coinsurance is the shared responsibility layer between deductible and out-of-pocket maximum. It applies to larger or more complex claims — the ones where the actual dollar exposure becomes significant. Understanding the percentage and how quickly it might accumulate is essential for planning around health care costs.",
