          "field",
          "Coordination of benefits prevents double-payment and defines each plan's responsibility. For dependents covered under two working parents' plans, or for individuals with both employer and Medicare coverage, understanding which plan is primary — and how the secondary fills gaps — can significantly reduce out-of-pocket cost.",
