          "noun",
          "A time deposit offered by banks and credit unions that pays a fixed interest rate in exchange for leaving a set amount of money untouched for a specified term — typically ranging from one month to five years. Early withdrawal typically incurs a penalty.",
          "course",
          "A CD exchanges liquidity for yield. The rate is locked at purchase, which is an advantage when rates are falling and a disadvantage when they rise. The penalty for early withdrawal is the cost of reclaiming flexibility — worth knowing before committing funds to a term that may no longer fit.",
