          "I-bonds have a purchase ceiling — $10,000 per person per year through TreasuryDirect, with an additional $5,000 available through tax refunds. Within that limit, they offer one of the most direct inflation protections available to individual savers. The one-year lockup and early redemption penalty in the first five years are the liquidity tradeoffs.",
