          "The way in which a jointly held account is legally structured, determining rights of survivorship and creditor access. The two most common forms are Joint Tenants with Rights of Survivorship (JTWROS), where the surviving owner inherits automatically, and Tenants in Common (TIC), where each owner's share passes through their estate.",
          "field",
