          "The Coverdell's contribution limit is low relative to education costs, but its coverage of K-12 expenses — which a 529 plan did not originally include — made it distinctive. For families with education savings strategies that span primary school through college, it can complement a 529. Income limits restrict high earners from contributing directly.",
