          "noun",
          "A 401(k) plan designed for self-employed individuals with no employees other than a spouse. It allows contributions in two capacities — as both employer and employee — enabling significantly higher annual contributions than a SEP-IRA or SIMPLE IRA in many income scenarios. Roth contribution options are available in some plans.",
          "course",
          "The solo 401(k) is the most powerful retirement savings vehicle available to the self-employed at most income levels. The dual contribution capacity — up to the employee deferral limit plus an employer profit-sharing contribution — can shelter a substantial portion of self-employment income. Plan administration requirements are modest when there are no employees.",
