          "field",
          "The SEP-IRA is easy to establish and administer — no annual filings, no complex plan documents. For sole proprietors and small business owners looking for a straightforward high-contribution vehicle, it is often the first choice. The limitation relative to a solo 401(k): no Roth option and no employee salary deferral component.",
          480,
