          28,
          "SIMPLE IRA",
          "/ˈsɪmpəl aɪ-ɑːr-eɪ/",
          "noun",
          "A Savings Incentive Match Plan for Employees — a retirement plan for small businesses with 100 or fewer employees. Employees can make salary deferrals up to an annual limit, and employers are required to make either matching contributions or non-elective contributions. Contribution limits are lower than 401(k) limits.",
          "course",
          "The SIMPLE IRA sits between the SEP-IRA and a full 401(k) in complexity and contribution capacity. It requires employer contributions — a mandatory cost — but provides employees with a salary deferral mechanism. For small business owners who want to offer a retirement benefit with minimal administrative burden, it is a practical starting point.",
