          32,
          "Backdoor Roth",
          "/ˈbækdɔːr roʊθ/",
          "noun",
          "A strategy that allows individuals whose income exceeds the Roth IRA contribution limits to effectively contribute to a Roth IRA by making a non-deductible traditional IRA contribution and then converting it to a Roth IRA. The conversion is taxable only on any earnings that accrued between contribution and conversion.",
          "course",
          "The backdoor Roth is a legal workaround for high earners locked out of direct Roth contributions. It requires attention to the pro-rata rule — if the contributor holds other pre-tax IRA funds, a portion of the conversion may be taxable. Converting promptly after contributing minimizes taxable earnings on the converted amount.",
          "To execute the backdoor Roth strategy: make a non-deductible traditional IRA contribution and promptly convert it to a Roth IRA, effectively funding a Roth account despite exceeding the direct income contribution limits. The mechanics are straightforward; the pro-rata rule is the variable that requires attention.",
          "field",
          "To backdoor Roth is to use the available legal path when the direct path is closed. The income limit applies to direct Roth contributions — not to conversions. The contribution goes in as non-deductible; the conversion moves it to Roth. Done quickly, the taxable amount is negligible. Done without checking existing IRA balances, the pro-rata rule can produce an unpleasant surprise.",
