          "field",
          "A direct rollover is the safest mechanism for moving an employer plan balance when changing jobs or retiring. The funds never leave the tax-advantaged system, no withholding is triggered, and there is no deadline pressure. Requesting a direct rollover rather than a check made out to the account holder prevents the most common rollover mistakes.",
