          "noun",
          "A provision of the IRS tax code that allows penalty-free withdrawals from an IRA or 401(k) before age 59½, provided the account holder takes a series of Substantially Equal Periodic Payments (SEPP) based on life expectancy. The payments must continue for at least five years or until age 59½, whichever is longer.",
          "course",
          "72(t) distributions are a specific and rigid tool for accessing retirement funds early without the 10 percent penalty. The calculation method is fixed, the payment schedule cannot be changed without triggering penalties retroactively, and the commitment is multi-year. It is a solution for a specific circumstance — not a casual early withdrawal mechanism.",
