          "Required Beginning Date",
          "/rɪˈkwaɪərd bɪˈɡɪnɪŋ deɪt/",
          "noun",
          "The date by which an account holder must begin taking Required Minimum Distributions from traditional IRAs and most employer-sponsored retirement plans. Currently April 1 of the year following the year in which the account holder reaches age 73 under current law, though the date has been adjusted several times by legislation.",
          "field",
          "The required beginning date is not optional — missing it triggers a significant penalty. Taking the first distribution by April 1 means two distributions in the first year, which can push income into a higher bracket. For most people, taking the first RMD in the year they turn 73 rather than waiting until April 1 of the following year is the cleaner approach.",
