        "noun",
        "Interest earned on interest already earned. Growth building on its own prior growth. The mechanism is simple. The implications are not. Given enough time, compound interest does not add to your money. It multiplies it, slowly at first, then in ways that will seem, in retrospect, almost impossible. This is not hyperbole. It is arithmetic behaving like magic. The enemy of compound interest is interruption: the withdrawal, the delay, the year you didn’t start. The Cost of Delay is not just a companion entry. It is the shadow of this one. A disciplined mind wants the system in place early. A curious mind wants to understand why it works. Here is why: time is doing the lifting. Your job is not to interrupt it.",
