        "20",
        "Zero-Based Budgeting",
        "/ˈzɪəroʊ beɪst ˈbʌdʒɪtɪŋ/",
        "noun",
        "A budgeting method in which every dollar of income is deliberately assigned to a specific purpose (expenses, savings, debt repayment, or investing) until the remaining balance reaches zero. No dollar is unaccounted for.",
        "course",
        "Zero-based budgeting does not mean spending everything. It means intentionally directing everything, including the amount going to savings and reserves. Its power is in forcing explicit decisions rather than allowing dollars to disappear into undefined spending. The monthly budget tells you what you planned; zero-based budgeting is the architecture behind the plan.  |  → see: Budget (Spending ⑩); The Gap",
