          "field",
          "The $10,000 SALT cap changed the math of itemizing for millions of homeowners in high-tax states. Property taxes and state income taxes that once pushed itemized deductions well above the standard deduction now frequently don't — making the standard deduction the better choice for households that previously itemized routinely. The cap is scheduled to expire and has been subject to ongoing legislative discussion.",
