          "course",
          "The one-year threshold is one of the most valuable lines in the tax code. Crossing it converts a gain taxed at ordinary rates into one taxed at significantly lower preferential rates. For investors with flexibility in timing, holding past the one-year mark is often the single most impactful tax decision available.",
