          "FIFO",
          "/ˈfaɪfoʊ/",
          "noun",
          "First In, First Out — a cost basis accounting method that assumes the oldest shares or units in a position are sold first. In a rising market, FIFO typically produces larger taxable gains because the older shares have a lower cost basis than more recently acquired ones.",
