          "Step-up in basis is one of the most powerful and underappreciated provisions in the tax code. It effectively forgives a lifetime of capital gains at death. For appreciated assets — a family home, a long-held stock portfolio, farmland — the tax savings can be enormous. Estate planning that accounts for step-up can preserve significantly more wealth for heirs than strategies that transfer appreciated assets during life.",
