          20,
          "Wash Sale Rule",
          "/wɒʃ seɪl ruːl/",
          "noun",
          "An IRS rule that disallows a capital loss deduction if the taxpayer purchases a substantially identical security within 30 days before or after the sale that generated the loss. The disallowed loss is added to the basis of the replacement security, deferring rather than permanently eliminating it.",
          "course",
          "The wash sale rule is triggered by the 61-day window — 30 days before the sale, the day of, and 30 days after. Selling at a loss and immediately repurchasing the same security to capture the tax benefit does not work. The loss is deferred, not lost — but it doesn't help the current year's tax bill. Replacement with a similar but not substantially identical security preserves the loss.",
          513,
