          "field",
          "Tax-loss harvesting converts an underperforming position into a tax asset without necessarily changing the portfolio's overall market exposure — a similar security can be purchased to maintain the investment profile while observing the wash sale window. Over time, consistent harvesting compounds in meaningful ways, particularly in larger taxable portfolios.",
