          "Gift Tax Return",
          "/ɡɪft tæks rɪˈtɜːrn/",
          "noun",
          "IRS Form 709, filed when a taxpayer makes gifts that exceed the annual exclusion amount to any one recipient in a calendar year, or when making certain special gifts such as contributions to 529 plans using five-year gift tax averaging. Filing the return does not necessarily mean tax is owed — it typically just records the use of lifetime exemption.",
          "field",
          "Most people who file a gift tax return owe no gift tax — they are simply reporting a use of their lifetime exemption. The confusion is common: filing Form 709 is not the same as paying gift tax. It is a tracking mechanism that reduces the remaining lifetime exemption by the amount reported. Tax is due only when cumulative taxable gifts exceed the lifetime exemption, which is currently very high.",
