          "course",
          "The high exemption means federal estate tax affects a very small percentage of estates under current law. However, the exemption is scheduled to revert to approximately half its current level at the end of 2025 unless Congress acts — a significant planning consideration for larger estates. State estate taxes, where applicable, often have much lower exemption thresholds.",
