          "field",
          "The generation-skipping tax closes a planning gap: without it, a grandparent could transfer wealth to grandchildren and skip one entire round of estate taxation that would have applied if the assets had passed through the middle generation. With the GST, the transfer is taxed at each generational level. Dynasty trusts and long-term trust structures are common planning tools for managing GST exposure.",
