        "A plan allocating income across expense categories, a structure for spending intentionally rather than reactively.  To assign income deliberately to specific categories before spending begins — making the decision about where money goes in advance rather than discovering afterward where it went.  To budget is not to constrain — it is to choose in advance. The budgeter who runs short in one category did not fail the budget. The budget surfaced a misalignment between intention and allocation. That is information, not punishment.",
