        "noun / verb",
        "A cognitive bias in which the first price encountered influences all subsequent judgments, often causing overpayment relative to actual value.  To anchor, in the behavioral sense, is to allow the first number encountered to disproportionately shape all subsequent evaluation — treating an arbitrary starting point as a meaningful reference even when it is not. Retailers anchor intentionally. Buyers who recognize the mechanism can resist it.  To be anchored is to evaluate a number not by what it is but by what it replaced. The antidote is arriving with an independent sense of value before the first number appears.",
