          "noun",
          "A valuation metric calculated by dividing the current share price by earnings per share. The P/E ratio reflects how much investors are willing to pay for each dollar of a company's earnings. A high P/E suggests high growth expectations or premium valuation; a low P/E may indicate undervaluation or low growth prospects.",
          "course",
          "The P/E ratio is the most commonly cited valuation metric in equity markets — and one of the most commonly misused. A high P/E is not inherently expensive if earnings are growing rapidly; a low P/E is not inherently cheap if earnings are deteriorating. Context — growth rate, industry, interest rate environment — is essential to interpretation.",
