          "Factor Investing",
          "/ˈfæktər ɪnˈvɛstɪŋ/",
          "noun",
          "An investment approach that systematically targets specific characteristics — factors — that research has identified as drivers of risk-adjusted returns. Common factors include value, momentum, quality, low volatility, and size. Factor investing sits between passive indexing and active stock selection.",
          "course",
          "Factor investing operationalizes academic research into portfolio construction. Rather than selecting individual stocks, factor investors tilt toward the characteristics that have historically been associated with excess returns. The persistent debate is whether factors persist because they represent genuine risk premia or because they have been arbitraged away since their discovery.",
