          "field",
          "ESG means different things to different investors. For some it is primarily values alignment — excluding industries or companies inconsistent with their principles. For others it is risk management — identifying companies whose governance or environmental exposure creates financial vulnerability. The two motivations are related but distinct, and the investment products built around ESG vary significantly in their methodology.",
          556,
