          "course",
          "High-yield bonds occupy the riskier end of the fixed income spectrum. Their higher coupons attract income-oriented investors, but the default risk and price volatility are meaningful. In recessions and credit crises, high-yield spreads widen dramatically — prices fall — as investors demand more compensation for risk they had previously underpriced.",
          559,
