          "field",
          "Convertible bonds sit at the intersection of debt and equity. They provide a floor from the bond component and a ceiling that rises with the stock. The tradeoff is a lower coupon than a straight bond and a higher price than the conversion value of the equity alone. They are complex instruments whose value depends on both interest rates and stock price movement.",
          560,
