          "Dollar-cost averaging is the mechanical implementation of investing discipline. It removes the timing decision — and the timing anxiety — from the process. The evidence suggests lump-sum investing outperforms it on average when a sum is available, because markets rise more often than they fall. But for regular contributions from income, DCA is the natural and effective default.",
