          60,
          "Covered Call",
          "/ˈkʌvərd kɔːl/",
          "noun",
          "An options strategy in which an investor who owns shares of a stock sells call options on those shares. The premium received from selling the call provides income and limited downside cushion. If the stock rises above the strike price, the shares may be called away — sold at the strike — capping the upside.",
