          "The covered call is the most commonly used options strategy among individual investors because it generates income from an existing position. The tradeoff is capped upside — if the stock surges, the owner participates only to the strike price. It is an income strategy, not a growth strategy, and is most effective on positions where significant appreciation is not expected.",
          "To sell call options against a stock position already owned, collecting a premium in exchange for accepting a ceiling on the position's upside. An investor who writes a covered call is monetizing the right to buy their shares at a higher price — receiving income now in exchange for capping how much they participate if the stock surges.",
