          "noun",
          "Borrowed money from a brokerage used to purchase securities, using the account's existing holdings as collateral. Margin amplifies both gains and losses — a 10 percent gain on a fully margined position produces a 20 percent return on the investor's equity; a 10 percent loss produces a 20 percent loss. A margin call occurs when account equity falls below the required minimum.",
          "course",
          "Margin introduces leverage into equity investing — and leverage is a multiplier in both directions. The math of losses on margin is particularly unforgiving: a 50 percent decline in a fully margined position wipes out equity entirely. Margin calls can force the liquidation of positions at the worst possible time. For most investors, margin represents a risk that the potential return does not adequately compensate.",
