          "field",
          "Short selling is directionally opposite to all other investing — the investor profits from decline rather than appreciation. It requires borrowing shares, paying a borrowing cost, and accepting theoretically unlimited loss risk if the position moves adversely. It is a legitimate risk management and price discovery mechanism, but one that demands both conviction and careful risk management.",
          "To borrow shares of a security and sell them in the open market with the intention of repurchasing them later at a lower price, profiting from the decline. An investor who shorts a stock is making a directional bet against it — and accepting that losses are theoretically unlimited if the price rises instead of falls.",
