          "The Sharpe ratio answers the question: how much return are you getting for the risk you're taking? A high-return investment with very high volatility may have a lower Sharpe ratio than a moderate-return investment with low volatility — meaning the moderate investment is delivering more reward per unit of risk. It is the most widely used single metric for comparing risk-adjusted performance.",
