        "12",
        "Time Freedom",
        "/ˈtīm ˈfrē-dəm/",
        "noun",
        "The ability to control one’s schedule, to work when, where, and on what one chooses.",
        "field",
        "Time freedom is often the real goal behind financial planning. Money is the mechanism; time is what it purchases. Defining how much time freedom you need helps calibrate how much financial independence is required.  |  → see: Financial Independence; Enough; Human Capital (Net $ Worth ⑨)",
        "48:30",
