        "13",
        "Downshift / Downshifting",
        "/ˈdauʍn-ˌshift/ · /ˈdauʍn-ˌshif-tiŋ/",
        "noun / verb",
        "Deliberately choosing lower income in exchange for a better quality of life, prioritizing time, health, or purpose over earnings.  To deliberately reduce income or professional intensity in exchange for time, health, purpose, or quality of life — choosing a smaller financial engine in service of a better-designed life. To downshift is to redefine success on different terms, not to surrender.  To downshift requires knowing the number: what does this life actually cost? The person who downshifts with a clear financial picture is making a strategy. The person who downshifts without one is making a wish.",
        "field",
        "Downshifting is a legitimate financial strategy. Not a failure of ambition. Its feasibility depends on having built the financial foundation that makes reduced income sustainable.  |  → see: Enough (Lifestyle ⑮); Financial Independence; Lifestyle Audit",
