          "Liquidity Ladder",
          "/lɪˈkwɪdɪti ˈlædər/",
          "noun",
          "A portfolio structure that divides assets into tiers based on time horizon and liquidity needs — cash for near-term expenses, short-term bonds for intermediate needs, and long-term growth assets for the distant future. The ladder ensures that short-term needs can be met without selling long-term assets during market downturns.",
          "course",
          "A liquidity ladder is time-horizon management made visible. By ensuring that near-term spending needs are funded from liquid assets, the investor can hold through market volatility in the long-term portion without being forced to sell at depressed prices. The psychological effect is as important as the financial one: knowing that the next two or three years of expenses are covered in stable assets makes it easier to leave the growth portfolio alone during a storm.",
          652,
